package org.geysermc.paletter.tools.model.infer;

import com.google.gson.JsonArray;
import com.google.gson.JsonObject;
import com.google.gson.JsonPrimitive;

import java.util.List;
import java.util.Map;
import java.util.TreeMap;
import java.util.TreeSet;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * {@code codegen/model/bds-feedback.json}: what the BDS content log says about the JSON schema, per component and
 * field path: members it does not know, fields it requires, list/object expectations, numeric ranges and minimum list
 * lengths. Generated by {@code spec infer} from the newest capture; the add-on generator reads it to build valid
 * bases and value sets in the next capture (BDS is the ground truth for validity, the docs are not always right).
 */
public final class Feedback {
    private static final Pattern PATH = Pattern.compile("-> (components|description|permutations\\[\\d+])(?: -> (.*?))?: (.*?)'?$");

    private final Map<String, Map<String, TreeSet<String>>> facts = new TreeMap<>();

    void add(String kind, String line) {
        Matcher m = PATH.matcher(line);
        if (!m.find()) {
            return;
        }
        String section = m.group(1);
        String rest = m.group(2) == null ? "" : m.group(2);
        String message = m.group(3).trim();
        List<String> parts = new java.util.ArrayList<>(List.of(rest.split(" -> ")));
        if (parts.size() == 1 && parts.get(0).isEmpty()) {
            parts.clear();
        }
        String component;
        if (section.equals("components")) {
            if (parts.isEmpty()) {
                return;
            }
            component = kind + ":" + parts.remove(0).replaceAll("\\[\\d+]", "");
        } else if (section.startsWith("permutations")) {
            component = "block:permutations";
            parts.add(0, "[]");
        } else if (!parts.isEmpty() && parts.get(0).equals("traits") && parts.size() > 1) {
            parts.remove(0);
            component = "block:trait:" + parts.remove(0);
        } else if (!parts.isEmpty() && parts.get(0).equals("states")) {
            parts.remove(0);
            component = "block:states";
            if (!parts.isEmpty()) {
                parts.set(0, "{}" + parts.get(0).replaceAll("^[^\\[]*", ""));
            }
        } else {
            component = kind + ":description";
        }
        String path = String.join(".", parts).replaceAll("\\[\\d+]", "[]").replace(".[]", "[]").replace(".{}", "{}");
        String fact = null;
        Matcher range;
        if (message.contains("not present in the Schema")) {
            fact = "unknown";
        } else if (message.contains("missing required field")) {
            fact = "required";
        } else if (message.contains("expected an array")) {
            fact = "array";
        } else if (message.contains("expected an object") || message.contains("expected a key/value object")) {
            fact = "object";
        } else if ((range = Pattern.compile("accepted range \\[(-?[\\d.]+), (-?[\\d.]+)]").matcher(message)).find()) {
            fact = "range " + range.group(1) + " " + range.group(2);
        } else if ((range = Pattern.compile("must be a number <= (-?[\\d.]+)").matcher(message)).find()) {
            fact = "max " + range.group(1);
        } else if ((range = Pattern.compile("must be a number >= (-?[\\d.]+)").matcher(message)).find()) {
            fact = "min " + range.group(1);
        } else if ((range = Pattern.compile("at least (\\d+) elements").matcher(message)).find()) {
            fact = "minItems " + range.group(1);
        } else if (message.contains("can only be used when") || message.contains("cannot be combined") || message.contains("Cannot have both")) {
            fact = "constraint " + message.replaceAll("for block: .*", "").trim();
        } else if (message.contains("expects one of the following strings")) {
            fact = "values " + message.replaceAll(".*following strings: ", "").replaceAll("\\.? ?Found:.*", "").trim();
        }
        if (fact != null) {
            facts.computeIfAbsent(component, k -> new TreeMap<>()).computeIfAbsent(path, k -> new TreeSet<>()).add(fact);
        }
    }

    JsonObject json() {
        JsonObject json = new JsonObject();
        json.addProperty("_comment", "Generated by spec infer from the content log of the newest capture; read by the add-on generator.");
        facts.forEach((component, paths) -> {
            JsonObject c = new JsonObject();
            paths.forEach((path, set) -> {
                JsonArray array = new JsonArray();
                set.forEach(f -> array.add(new JsonPrimitive(f)));
                c.add(path, array);
            });
            json.add(component, c);
        });
        return json;
    }
}
